/* Private course transport. No course content is written to browser storage. */
(function(root,factory){'use strict';const api=factory(root);if(typeof module==='object'&&module.exports)module.exports=api;else root.DegreeLearning=api;}(typeof globalThis!=='undefined'?globalThis:this,function(root){
  'use strict';
  const KINDS=Object.freeze({writing:'Writing project',study:'Study help',quiz:'Practice quiz',flashcards:'Flashcards',presentation:'Presentation',discussion:'Discussion'});
  const FEEDBACK_REASONS=Object.freeze({wrong_answer:'The answer seems wrong',unclear_steps:'The steps are unclear',missed_question:'It missed my question',source_issue:'There’s a source problem',unnatural_style:'Writing feels unnatural',other:'Something else'});
  const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
  function feedbackReceipt(value){if(value?.workflow!=='learning-homework'||typeof value.requestId!=='string'||!UUID.test(value.requestId))return null;const feedback=value.feedback;if(!feedback||!Object.hasOwn(feedback,'rating')||![null,'helpful','nothelpful'].includes(feedback.rating))return null;const reason=feedback.reason??null;if(reason!==null&&!Object.hasOwn(FEEDBACK_REASONS,reason)||feedback.rating!=='nothelpful'&&reason!==null)return null;return{requestId:value.requestId,feedback:{rating:feedback.rating,reason}};}
  function feedbackBody(rating,reason=null){if(!['helpful','nothelpful','clear'].includes(rating))throw Error('Choose Helpful, Not helpful or Clear feedback.');if(reason!==null&&!Object.hasOwn(FEEDBACK_REASONS,reason))throw Error('Choose a reason from the list.');return{rating,reason:rating==='nothelpful'?reason:null};}
  function feedbackController(client,projectId,runUsage){const receipt=feedbackReceipt(runUsage);if(typeof projectId!=='string'||!UUID.test(projectId)||!receipt)throw Error('This result is not available for feedback.');let saved=receipt.feedback,pending=false;const snapshot=()=>({pending,feedback:{...saved}});async function update(rating,reason=null){if(pending)return snapshot();const body=feedbackBody(rating,reason);pending=true;try{const response=await client.api('/projects/'+encodeURIComponent(projectId)+'/history/'+encodeURIComponent(receipt.requestId)+'/feedback',{method:'POST',body}),confirmed=feedbackReceipt(response.runUsage);if(!confirmed||confirmed.requestId!==receipt.requestId||confirmed.feedback.rating!==(rating==='clear'?null:rating)||confirmed.feedback.reason!==body.reason)throw Error('Your feedback could not be confirmed. Try again.');saved=confirmed.feedback;pending=false;return snapshot();}finally{pending=false;}}return Object.freeze({snapshot,update,requestId:receipt.requestId});}
  // Export review uses provided details only. It never fills missing people, dates or institutions.
  function wordMetadata(project={},course={},user={}){const artifact=project.artifact||{},provided=artifact.documentMetadata||{},text=(value,max)=>typeof value==='string'?Array.from(value.trim()).slice(0,max).join(''):'',name=text(user.displayName,120);return{title:text(provided.title||project.title,200),studentName:text(provided.studentName,120)||(/^student$/i.test(name)?'':name),instructor:text(provided.instructor,120),institution:text(provided.institution,160),course:text(provided.course||course.title,160),date:text(provided.date,80),lastName:text(provided.lastName,80)};}
  function reviewFlags(artifact){return items(artifact?.review?.flags).slice(0,8).filter(flag=>flag&&['input','review','blocking'].includes(flag.severity)&&['notes','sources','format','result'].includes(flag.target)&&typeof flag.message==='string'&&flag.message.trim()&&typeof flag.nextAction==='string'&&flag.nextAction.trim()).map(flag=>({id:typeof flag.id==='string'?flag.id.slice(0,80):'',kind:typeof flag.kind==='string'?flag.kind.slice(0,80):'',severity:flag.severity,target:flag.target,message:flag.message.slice(0,1000),nextAction:flag.nextAction.slice(0,500)}));}
  function researchRetryAction(kind,current){if(kind==='writing')return current==='plan'?'plan':'draft';if(kind==='presentation'||kind==='discussion')return current==='plan'?'plan':kind;if(['study','quiz','flashcards'].includes(kind))return['study','quiz','flashcards'].includes(current)?current:kind;return null;}
  function safeURL(value){try{if(typeof value!=='string'||value.length>1500)return null;const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}}
  function checkoutURL(value){try{if(typeof value!=='string'||value.length>4096)return null;const u=new URL(value);return u.protocol==='https:'&&u.hostname==='checkout.stripe.com'&&!u.username&&!u.password&&!u.port?u.href:null;}catch{return null;}}
  function escape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function items(value){return Array.isArray(value)?value:[];}
  function sourceValues(entries){const values=[];for(const entry of entries){const url=String(entry.url||'').trim(),title=String(entry.title||'').trim(),excerpt=String(entry.excerpt||'').trim();if(!url&&!title&&!excerpt)continue;if(!safeURL(url))throw Error('Add a full https:// link for each source.');if(!title)throw Error('Give each source a title.');if(title.length>200||excerpt.length>4000)throw Error('Keep source titles under 200 characters and passages under 4,000.');values.push({url,title,...(excerpt?{excerpt}:{})});}if(values.length>8)throw Error('Use up to eight sources for this project.');return values;}
  function markdown(project,course){const result=project?.artifact||{},parts=['# '+String(project?.title||'Course project'),''];if(course?.title)parts.push('Course: '+course.title+(course.provider?' · '+course.provider:''),'');if(result.summary)parts.push(String(result.summary),'');if(result.content)parts.push(String(result.content),'');const sources=items(result.sources);if(sources.length){parts.push('## Sources','');for(const [i,s]of sources.entries())parts.push((i+1)+'. '+String(s.title||s.url||'Source')+(safeURL(s.url)?' — '+safeURL(s.url):''));parts.push('');}if(result.nextStep)parts.push('## Next step','',String(result.nextStep),'');return parts.join('\n');}
  function filename(value,ext){const name=String(value||'course-project').normalize('NFKD').replace(/[^a-z0-9-]+/gi,'-').replace(/^-+|-+$/g,'').slice(0,80)||'course-project';return name+'.'+ext;}
  function create(options={}){
    const fetcher=options.fetch||((...args)=>root.fetch(...args));
    async function api(path,options={}){const method=options.method||'GET';let response;try{response=await fetcher('/api/learning'+path,{method,credentials:'same-origin',cache:'no-store',redirect:'error',headers:{Accept:'application/json',...(method!=='GET'?{'Content-Type':'application/json','X-Learning-Request':'1'}:{})},...(options.body===undefined?{}:{body:JSON.stringify(options.body)})});}catch{const error=Error('We couldn’t reach your course workspace. Your saved projects are still in your account.');error.code='network_error';throw error;}let data;try{if(!(response.headers.get('Content-Type')||'').toLowerCase().includes('application/json'))throw Error();data=await response.json();if(!data||typeof data!=='object'||Array.isArray(data))throw Error();}catch{const error=Error('Your workspace returned an unreadable response. Try checking your saved project again.');error.status=response.status;error.code='invalid_response';throw error;}if(!response.ok){const error=Error(typeof data.error==='string'?data.error:'Your course workspace is temporarily unavailable.');error.status=response.status;error.code=data.code;error.details=data;throw error;}return data;}
    return Object.freeze({api});
  }
  return Object.freeze({create,safeURL,checkoutURL,escape,items,sourceValues,markdown,filename,feedbackReceipt,feedbackBody,feedbackController,wordMetadata,reviewFlags,researchRetryAction,feedbackReasons:FEEDBACK_REASONS,kinds:KINDS});
}));
